import React from "react";
import { useGame } from "../../../hooks/EnJuego";

export const EstadoJugador: React.FC = () => {
  const { turn } = useGame();

  return (
    <h2 style={{ color: "white"}}>
      Turno del Jugador:{" "}
      <span style={{ color: turn === "X" ? "#3182ce" : "#e53e3e" }}>
        {turn}
      </span>
    </h2>
  );
};

export default EstadoJugador;
